function openModifierFor(record){modifierContext="all";modifierRecord=null;$("modifier-title").textContent=`Modify: ${record.genotype}`;$("modifier-experiment").value=barcodeFor(record);$("modifier-message").textContent="Choose the planned collection, aging, fertility-assay, or fly-count date to change.";$("modifier-load").click();page("modifier-detail-page")}
function experimentNotesPreview(record){const notes=observations().filter(note=>note.experimentId===record.id);if(!notes.length)return `<p class="experiment-notes-empty">No experiment notes yet.</p>`;return `<details class="experiment-notes"><summary>📝 ${notes.length} experiment note${notes.length===1?"":"s"}</summary><div class="experiment-notes-list">${notes.map(note=>`<article><p><strong>${pretty(note.date)}</strong> · ${escapeText(note.note)}</p>${note.photo?`<img src="${note.photo.data}" alt="Photo attached to this experiment note">`:""}</article>`).join("")}</div></details>`}
function renderExperiments(){const records=workflowSaved().filter(record=>experimentStatus(record)===experimentView),box=$("experiments-list"),label=experimentView==="ongoing"?"current":experimentView;box.innerHTML=records.length?records.map(record=>{const events=workflowEvents(record),end=events[events.length-1].time;return `<div class="saved-card experiment-card"><div><button class="secondary" data-open-experiment="${record.id}" type="button">(${barcodeFor(record)}) ${escapeText(record.genotype)}</button><p>${record.direction==="25to18"?"25°C → 18°C":"18°C → 25°C"} · ${label} · ${formatTime(record.start)} to ${formatTime(end)}</p>${experimentNotesPreview(record)}</div>${threeDotMenu("experiment",record.id)}</div>`}).join(""):`<p class="hint">No ${label} experiments.</p>`;box.querySelectorAll("[data-open-experiment]").forEach(button=>button.onclick=()=>openExperimentControl(workflowSaved().find(record=>record.id===button.dataset.openExperiment)));box.querySelectorAll("[data-edit-experiment]").forEach(button=>button.onclick=()=>editExperiment(button.dataset.editExperiment));box.querySelectorAll("[data-delete-experiment]").forEach(button=>button.onclick=()=>deleteExperiment(button.dataset.deleteExperiment))}
document.head.insertAdjacentHTML("beforeend",`<style>.experiment-card{align-items:flex-start}.experiment-notes{margin-top:.7rem;padding:.55rem .65rem;border-radius:9px;background:#f6f7fc;border:1px solid #dfe2ee}.experiment-notes summary{cursor:pointer;color:#3e4f86;font-weight:700}.experiment-notes-list{display:grid;gap:.55rem;margin-top:.65rem}.experiment-notes-list article{padding:.6rem .7rem;border-left:3px solid #8b9dcb;background:#fff;border-radius:6px}.experiment-notes-list p{margin:0;line-height:1.45}.experiment-notes-list img{display:block;max-width:170px;max-height:130px;object-fit:cover;border-radius:6px;margin-top:.55rem}.experiment-notes-empty{margin:.65rem 0 0;color:#737383;font-size:.88rem}</style>`);
