function photoToData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,data:reader.result});reader.onerror=()=>reject();reader.readAsDataURL(file)})}
$("observation-form").onsubmit=async event=>{event.preventDefault();const id=$("observation-experiment").value,date=$("observation-date").value,note=$("observation-note").value.trim(),record=workflowSaved().find(item=>item.id===id),file=$("observation-photo")?.files[0];if(!record||experimentStatus(record)!=="ongoing"||!date||!note){$("observation-message").textContent="Notes can only be saved for a current experiment.";return}if(file&&file.size>2*1024*1024){$("observation-message").textContent="Choose a photo smaller than 2 MB so it can be saved safely in this app.";return}let photo=null;if(file){try{photo=await photoToData(file)}catch{$("observation-message").textContent="The photo could not be attached. Please try again.";return}}const items=observations();items.unshift({id:crypto.randomUUID(),type:"note",experimentId:id,experimentName:record.genotype,date,note,photo});try{localStorage.setItem(observationKey,JSON.stringify(items))}catch{$("observation-message").textContent="There is not enough local space to save this photo. Try a smaller image.";return}$("observation-note").value="";if($("observation-photo"))$("observation-photo").value="";$("observation-message").textContent=photo?"Note and photo saved.":"Note saved.";renderObservations()};

const stockKey="fly-manager-stocks-v1";
function stocks(){try{return JSON.parse(localStorage.getItem(stockKey))||[]}catch{return[]}}
function saveStocks(items){localStorage.setItem(stockKey,JSON.stringify(items))}
function nextFridayForStock(stock){const now=new Date(),setup=new Date(`${stock.setup}T12:00:00`),base=setup>now?setup:now;base.setHours(12,0,0,0);let offset=(5-base.getDay()+7)%7;if(offset===0)offset=7;base.setDate(base.getDate()+offset);return base}
function stockTasks(stock,forCalendar=false){const today=dateValue(new Date()),items=[],start=nextFridayForStock(stock);for(let index=0;index<16;index++){const taskDate=dateValue(addHours(start,index*7*24));if(forCalendar?taskDate>=today:taskDate===today)items.push({id:`stock:${stock.id}:${taskDate}`,source:"Stock management",title:`${stock.genotype}: ${index%2===0?"Flip stock":"Plug stock"}`,date:taskDate})}return items}
