function ensureStockPages(){const page=$("stock-page");if(page.dataset.ready)return;page.dataset.ready="true";page.innerHTML=`<button class="secondary back" data-page="home-page">← Home</button><div class="intro"><h2>Stock Management</h2><p>Add a stock, manage its saved weekly care schedule, or check whether a stock is available.</p></div><div class="menu-grid"><button class="menu-card" type="button" data-stock-page="input"><b>➕<br>Input New Stock</b><span>Record a new stock and begin its care schedule.</span></button><button class="menu-card" type="button" data-stock-page="existing"><b>🧪<br>Manage Existing Stock</b><span>See saved stocks and their flip/plug schedules.</span></button><button class="menu-card" type="button" data-stock-page="availability"><b>✓<br>Stock Availability</b><span>Check whether a saved stock should be available on a date.</span></button></div>`;document.querySelectorAll('[data-page="home-page"]').forEach(button=>button.onclick=()=>page("home-page"));page.insertAdjacentHTML("afterend",`<section id="stock-input-page" class="page hidden"><button class="secondary back" type="button" data-stock-back>← Stock Management</button><div class="intro"><h2>Input New Stock</h2><p>Save the stock details once. It will then appear under Manage Existing Stock.</p></div><section class="panel"><form id="stock-input-form"><div class="form-grid"><label>Stock species<input id="stock-species" required placeholder="e.g., Drosophila melanogaster"></label><label>Stock genotype<input id="stock-genotype" required placeholder="e.g., w1118"></label><label>Stock sex<select id="stock-sex" required><option value="Female">Female</option><option value="Male">Male</option><option value="Mixed">Mixed</option></select></label><label>Experiment this stock is for<select id="stock-experiment"></select></label><label>Date stock is set up<input id="stock-setup" type="date" required></label></div><button>Save new stock</button></form><p id="stock-input-message" class="hint" aria-live="polite"></p></section></section><section id="stock-existing-page" class="page hidden"><button class="secondary back" type="button" data-stock-back>← Stock Management</button><div class="intro"><h2>Manage Existing Stock</h2><p>Each saved stock is scheduled to flip this week and plug the following week, then repeat weekly.</p></div><section class="panel"><div id="existing-stock-list"></div></section></section><section id="stock-availability-page" class="page hidden"><button class="secondary back" type="button" data-stock-back>← Stock Management</button><div class="intro"><h2>Stock Availability</h2><p>Choose a date to check whether at least one saved stock should be available.</p></div><section class="panel"><form id="stock-availability-form" class="form-grid"><label>Date needed<input id="stock-needed-date" type="date" required></label><div><button>Check availability</button></div></form><div id="stock-availability-result" aria-live="polite"></div></section></section>`);page.querySelectorAll("[data-stock-page]").forEach(button=>button.onclick=()=>{if(button.dataset.stockPage==="input")openStockInput();if(button.dataset.stockPage==="existing"){renderExistingStocks();page("stock-existing-page")}if(button.dataset.stockPage==="availability")page("stock-availability-page")});document.querySelectorAll("[data-stock-back]").forEach(button=>button.onclick=()=>page("stock-page"));$("stock-input-form").onsubmit=saveNewStock;$("stock-availability-form").onsubmit=checkStockAvailability}
function openStockInput(){const select=$("stock-experiment");select.innerHTML=`<option value="Fertility Assay">Fertility Assay</option><option value="Other">Other</option>`;if(!$("stock-other-experiment")){select.closest("label").insertAdjacentHTML("afterend",`<label id="stock-other-experiment-label" class="hidden">Specify other experiment<input id="stock-other-experiment" placeholder="Name of experiment"></label>`);select.onchange=()=>$("stock-other-experiment-label").classList.toggle("hidden",select.value!=="Other")}$(("stock-setup")).value=dateValue(new Date());$("stock-input-message").textContent="";page("stock-input-page")}
function saveNewStock(event){event.preventDefault();const species=$("stock-species").value.trim(),genotype=$("stock-genotype").value.trim(),sex=$("stock-sex").value,experimentType=$("stock-experiment").value,other=$("stock-other-experiment")?.value.trim()||"",setup=$("stock-setup").value,experimentName=experimentType==="Other"?other:"Fertility Assay";if(!species||!genotype||!setup||(experimentType==="Other"&&!other)){$("stock-input-message").textContent="Complete all fields, including the name of the other experiment.";return}const items=stocks();items.unshift({id:crypto.randomUUID(),species,genotype,sex,experimentType,experimentName,setup});saveStocks(items);$("stock-input-form").reset();$("stock-input-message").textContent="Stock saved. Its weekly flip/plug tasks are now included in Tasks.";renderTasks()}
function renderExistingStocks(){const items=stocks(),box=$("existing-stock-list");box.innerHTML=items.length?items.map(stock=>{const next=stockTasks(stock,true)[0];return `<div class="saved-card"><div><h3>${escapeText(stock.genotype)} · ${escapeText(stock.sex)}</h3><p>${escapeText(stock.species)} · for ${escapeText(stock.experimentName)} · set up ${pretty(stock.setup)}</p><p class="hint">Barcode: ${stockBarcode(stock)} · Next task: ${next?`${next.title} on ${pretty(next.date)}`:"No upcoming task"}</p></div>${threeDotMenu("stock",stock.id)}</div>`}).join(""):`<p class="hint">No stocks have been added yet.</p>`;box.querySelectorAll("[data-edit-stock]").forEach(button=>button.onclick=()=>editStock(button.dataset.editStock));box.querySelectorAll("[data-delete-stock]").forEach(button=>button.onclick=()=>deleteStock(button.dataset.deleteStock))}
