function threeDotMenu(type,id){return `<details style="position:relative;align-self:flex-start"><summary aria-label="More options" title="More options" style="cursor:pointer;font-size:1.5rem;line-height:1;padding:.1rem .4rem">⋯</summary><div style="position:absolute;right:0;z-index:2;min-width:7rem;padding:.45rem;background:#fff;border:1px solid #cbd9cf;border-radius:.5rem;box-shadow:0 .25rem .8rem #0002"><button class="secondary" type="button" data-edit-${type}="${id}">Edit</button><button class="secondary" type="button" data-delete-${type}="${id}" style="margin-top:.35rem">Delete</button></div></details>`}
