function deleteExperiment(id){const record=workflowSaved().find(item=>item.id===id);if(!record||!confirm(`Move ${record.genotype} and its saved schedule to Trash?`))return;const experimentNotes=observations().filter(note=>note.experimentId===id),completed=completedTasks(),experimentCompleted=Object.fromEntries(Object.entries(completed).filter(([key])=>key.includes(`:${id}:`)));moveToTrash("Experiment",{record,notes:experimentNotes,completed:experimentCompleted});localStorage.setItem(workflowKey,JSON.stringify(workflowSaved().filter(item=>item.id!==id)));localStorage.setItem(observationKey,JSON.stringify(observations().filter(note=>note.experimentId!==id)));Object.keys(experimentCompleted).forEach(key=>delete completed[key]);localStorage.setItem(completedTaskKey,JSON.stringify(completed));renderExperiments();renderTasks()}
