function exportObservation(id){const item=observations().find(note=>note.id===id);if(!item)return;const blob=new Blob([JSON.stringify(item,null,2)],{type:"application/json"}),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`${item.experimentName.replace(/[^a-z0-9]+/gi,"-")}-observation-${item.date}.json`;link.click();URL.revokeObjectURL(link.href)}
function deleteObservation(id){const item=observations().find(note=>note.id===id);if(!item||!confirm("Move this observation note to Trash?"))return;moveToTrash("Observation note",{note:item});localStorage.setItem(observationKey,JSON.stringify(observations().filter(note=>note.id!==id)));renderObservations()}
function checkStockAvailability(event){event.preventDefault();const needed=$("stock-needed-date").value,query=$("stock-availability-search").value.trim(),normalized=query.toUpperCase(),matches=stocks().filter(stock=>!query||stock.genotype.toLowerCase().includes(query.toLowerCase())||stockBarcode(stock)===normalized),available=matches.filter(stock=>stock.setup<=needed),box=$("stock-availability-result");if(!needed||!query){box.innerHTML=`<p class="hint">Enter a strain name or barcode and the date needed.</p>`;return}box.innerHTML=available.length?`<p><strong>Yes — ${escapeText(available[0].genotype)} should be available on ${pretty(needed)}.</strong></p><p class="hint">Barcode: ${stockBarcode(available[0])}</p>`:`<p><strong>No matching saved stock is set up by ${pretty(needed)}.</strong></p>`}
