const trashKey="fly-manager-trash-v1";
function trashItems(){try{return JSON.parse(localStorage.getItem(trashKey))||[]}catch{return[]}}
function saveTrash(items){localStorage.setItem(trashKey,JSON.stringify(items))}
function moveToTrash(type,data){const items=trashItems();items.unshift({id:crypto.randomUUID(),type,data,deletedAt:new Date().toISOString()});saveTrash(items)}
function trashTitle(item){if(item.type==="Experiment")return `${item.data.record.genotype} experiment`;if(item.type==="Stock")return `${item.data.stock.genotype} stock`;if(item.type==="Lab note")return item.data.note.title||"Untitled note";if(item.type==="Cross plan")return item.data.cross.name||`${item.data.cross.female} × ${item.data.cross.male}`;return `${item.data.note.experimentName} observation note`}
function renderTrash(){const items=trashItems(),box=$("trash-list");box.innerHTML=items.length?items.map(item=>`<div class="saved-card"><div><h3>${escapeText(trashTitle(item))}</h3><p>${item.type} · moved to Trash ${formatTime(item.deletedAt)}</p></div><div><button class="secondary" type="button" data-restore-trash="${item.id}">Restore</button><button class="secondary" type="button" data-delete-trash="${item.id}">Delete forever</button></div></div>`).join(""):`<p class="hint">Trash is empty.</p>`;box.querySelectorAll("[data-restore-trash]").forEach(button=>button.onclick=()=>restoreTrash(button.dataset.restoreTrash));box.querySelectorAll("[data-delete-trash]").forEach(button=>button.onclick=()=>deleteTrashForever(button.dataset.deleteTrash))}
function restoreTrash(id){const item=trashItems().find(entry=>entry.id===id);if(!item)return;if(item.type==="Experiment"){const records=workflowSaved();if(!records.some(record=>record.id===item.data.record.id)){records.unshift(item.data.record);localStorage.setItem(workflowKey,JSON.stringify(records))}const notes=[...observations(),...item.data.notes.filter(note=>!observations().some(current=>current.id===note.id))];localStorage.setItem(observationKey,JSON.stringify(notes));localStorage.setItem(completedTaskKey,JSON.stringify({...completedTasks(),...item.data.completed}))}if(item.type==="Stock"){const items=stocks();if(!items.some(stock=>stock.id===item.data.stock.id)){items.unshift(item.data.stock);saveStocks(items)}}if(item.type==="Observation note"){const notes=observations();if(!notes.some(note=>note.id===item.data.note.id)){notes.unshift(item.data.note);localStorage.setItem(observationKey,JSON.stringify(notes))}}if(item.type==="Lab note"){const notes=labNotes();if(!notes.some(note=>note.id===item.data.note.id)){notes.unshift(item.data.note);saveLabNotes(notes)}}if(item.type==="Cross plan"){const crosses=crossPlans();if(!crosses.some(cross=>cross.id===item.data.cross.id)){crosses.unshift(item.data.cross);saveCrossPlans(crosses)}}saveTrash(trashItems().filter(entry=>entry.id!==id));renderTrash();renderExperiments();renderExistingStocks();renderTasks();renderObservations();renderLabNotes?.();renderCrossPlans?.()}
function deleteTrashForever(id){const item=trashItems().find(entry=>entry.id===id);if(!item||!confirm(`Permanently delete ${trashTitle(item)}? This cannot be undone.`))return;saveTrash(trashItems().filter(entry=>entry.id!==id));renderTrash()}
