function geneticsInput(column,row,number){const value=dataSheetCellValue(row[column.key]??"");return `<input data-grid-field="${column.key}"${column.type?` type="${column.type}"`:""}${column.type==="number"?" min=\"0\" step=\"1\"":""} value="${value}" aria-label="${column.label}, row ${number}">`}
spreadsheetRow=function(row={},number){return `<tr data-grid-row data-row-id="${dataSheetCellValue(row.id||"")}"><th class="sheet-row-number" scope="row">${number}</th>${geneticsSheetColumns.map(column=>`<td>${geneticsInput(column,row,number)}</td>`).join("")}<td class="sheet-delete"><button class="secondary" type="button" data-delete-grid-row title="Remove row ${number}" aria-label="Remove row ${number}">×</button></td></tr>`};
spreadsheetGridMarkup=function(record){const saved=spreadsheetRows(record),blankRows=Math.max(12,20-saved.length),rows=[...saved,...Array.from({length:blankRows},()=>({}))];return `<div class="excel-grid-wrap"><table class="excel-grid genetics-sheet"><thead><tr><th class="sheet-corner" aria-label="Row number"></th>${geneticsSheetColumns.map(column=>`<th>${column.label}</th>`).join("")}<th aria-label="Remove row"></th></tr></thead><tbody>${rows.map((row,index)=>spreadsheetRow(row,index+1,record)).join("")}</tbody></table></div>`};
spreadsheetInputRows=function(container,record){const rows=[];container.querySelectorAll("[data-grid-row]").forEach(element=>{const row={};geneticsSheetColumns.forEach(column=>row[column.key]=element.querySelector(`[data-grid-field="${column.key}"]`).value.trim());if(!geneticsSheetColumns.some(column=>row[column.key]))return;row.id=element.dataset.rowId||crypto.randomUUID();if(record){row.experimentId=record.id;row.experimentBarcode=barcodeFor(record);row.experimentName=record.genotype}rows.push(row)});return{rows,incomplete:[]}};
