// Spreadsheet-style data sheets.  The main sheet keeps all measurements, while
// every saved experiment opens its own filtered sheet from the experiment menu.
const dataSheetColumns=["date","index","type","measurement","value","unit","notes"];
const dataSheetTypeOptions=["Fly count","Fertility assay","Temperature","Humidity","Other"];
let activeExperimentDataSheet=null;
function dataSheetCellValue(value){return escapeText(value??"")}
function dataSheetTypeSelect(value){return `<select data-grid-field="type">${dataSheetTypeOptions.map(option=>`<option${option===(value||"Fly count")?" selected":""}>${option}</option>`).join("")}</select>`}
function spreadsheetRow(row={},number,record){const defaultIndex=record?"":"",today=dateValue(new Date());return `<tr data-grid-row data-row-id="${dataSheetCellValue(row.id||"")}"><th class="sheet-row-number" scope="row">${number}</th><td><input data-grid-field="date" type="date" value="${dataSheetCellValue(row.date||today)}" aria-label="Date, row ${number}"></td><td><input data-grid-field="index" value="${dataSheetCellValue(row.index||defaultIndex)}" placeholder="MT18253-01" aria-label="Vial index, row ${number}"></td><td>${dataSheetTypeSelect(row.type)}</td><td><input data-grid-field="measurement" value="${dataSheetCellValue(row.measurement)}" placeholder="e.g., female progeny" aria-label="Measurement, row ${number}"></td><td><input data-grid-field="value" value="${dataSheetCellValue(row.value)}" placeholder="e.g., 42" aria-label="Value, row ${number}"></td><td><input data-grid-field="unit" value="${dataSheetCellValue(row.unit)}" placeholder="flies" aria-label="Unit, row ${number}"></td><td><input data-grid-field="notes" value="${dataSheetCellValue(row.notes)}" placeholder="Optional note" aria-label="Notes, row ${number}"></td><td class="sheet-delete"><button class="secondary" type="button" data-delete-grid-row title="Remove row ${number}" aria-label="Remove row ${number}">×</button></td></tr>`}
function spreadsheetRows(record){return dataSheetRows().filter(row=>record?row.experimentId===record.id:true)}
function spreadsheetGridMarkup(record){const saved=spreadsheetRows(record),blankRows=Math.max(12,20-saved.length),rows=[...saved,...Array.from({length:blankRows},()=>({}))];return `<div class="excel-grid-wrap"><table class="excel-grid"><thead><tr><th class="sheet-corner" aria-label="Row number"></th><th>Date</th><th>Vial / assay index</th><th>Data type</th><th>Measurement</th><th>Value</th><th>Unit</th><th>Notes</th><th aria-label="Remove row"></th></tr></thead><tbody>${rows.map((row,index)=>spreadsheetRow(row,index+1,record)).join("")}</tbody></table></div>`}
function appendSpreadsheetRows(container,record,count=10){const body=container.querySelector("tbody"),start=body.querySelectorAll("tr").length;body.insertAdjacentHTML("beforeend",Array.from({length:count},(_,index)=>spreadsheetRow({},start+index+1,record)).join(""));bindSpreadsheetRowDeletes(container,record)}
function bindSpreadsheetRowDeletes(container,record){container.querySelectorAll("[data-delete-grid-row]").forEach(button=>button.onclick=()=>{const row=button.closest("tr"),id=row.dataset.rowId;if(id){if(!confirm("Remove this saved data row?"))return;saveDataSheetRows(dataSheetRows().filter(item=>item.id!==id));renderSpreadsheetGrid(container,record)}else row.remove()})}
function renderSpreadsheetGrid(container,record){if(!container)return;container.innerHTML=spreadsheetGridMarkup(record);bindSpreadsheetRowDeletes(container,record)}
function spreadsheetInputRows(container,record){const rows=[],incomplete=[];container.querySelectorAll("[data-grid-row]").forEach(element=>{const row={};dataSheetColumns.forEach(field=>row[field]=element.querySelector(`[data-grid-field="${field}"]`).value.trim());const hasValues=dataSheetColumns.some(field=>row[field]);if(!hasValues)return;row.index=row.index.toUpperCase();if(!row.date||!row.index||!row.measurement||!row.value){incomplete.push(element.querySelector(".sheet-row-number").textContent);return}row.id=element.dataset.rowId||crypto.randomUUID();if(record){row.experimentId=record.id;row.experimentBarcode=barcodeFor(record);row.experimentName=record.genotype}rows.push(row)});return{rows,incomplete}}
function saveSpreadsheetGrid(container,record,message){const result=spreadsheetInputRows(container,record);if(result.incomplete.length){message.textContent=`Complete Date, Vial / assay index, Measurement, and Value in row${result.incomplete.length===1?"":"s"} ${result.incomplete.join(", ")}.`;return}const existing=dataSheetRows(),untouched=record?existing.filter(row=>row.experimentId!==record.id):[];saveDataSheetRows(record?[...result.rows,...untouched]:result.rows);renderSpreadsheetGrid(container,record);message.textContent=`${result.rows.length} data row${result.rows.length===1?"":"s"} saved.`}
function downloadSpreadsheetRows(record){const headers=["Date","Experimental / vial index","Data type","Measurement","Value","Unit","Notes"],rows=spreadsheetRows(record),cell=value=>`<Cell><Data ss:Type="String">${escapeSpreadsheet(value)}</Data></Cell>`,title=record?`${barcodeFor(record)} Data`:"Fly Manager Data",xml=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="header"><Interior ss:Color="#142B59" ss:Pattern="Solid"/><Font ss:Color="#FFFFFF" ss:Bold="1"/></Style></Styles><Worksheet ss:Name="Data Sheet"><Table><Row>${headers.map(header=>`<Cell ss:StyleID="header"><Data ss:Type="String">${header}</Data></Cell>`).join("")}</Row>${rows.map(row=>`<Row>${[row.date,row.index,row.type,row.measurement,row.value,row.unit||"",row.notes||""].map(cell).join("")}</Row>`).join("")}</Table></Worksheet></Workbook>`,blob=new Blob([xml],{type:"application/vnd.ms-excel"}),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`${record?barcodeFor(record):"fly-manager"}-data-sheet.xls`;link.click();URL.revokeObjectURL(link.href)}
function setupSpreadsheetPage(pageId,record){const grid=$(pageId+"-grid"),message=$(pageId+"-message");renderSpreadsheetGrid(grid,record);$(pageId+"-save").onclick=()=>saveSpreadsheetGrid(grid,record,message);$(pageId+"-add").onclick=()=>appendSpreadsheetRows(grid,record);$(pageId+"-download").onclick=()=>downloadSpreadsheetRows(record)}
function upgradeMainDataSheet(){const dataPage=$("data-sheet-page");if(!dataPage||$("main-data-sheet-grid"))return;dataPage.querySelector(".intro").innerHTML="<h2>Data Sheet</h2><p>Type straight into the cells, then save the sheet. Downloaded sheets open in Excel.</p>";dataPage.querySelectorAll(".panel").forEach(panel=>panel.remove());dataPage.insertAdjacentHTML("beforeend",`<section class="panel spreadsheet-panel"><div class="spreadsheet-toolbar"><div><h3>All data rows</h3><p class="hint">For a single experiment, open its Data Sheet from that experiment.</p></div><div><button id="main-data-sheet-save" type="button">Save Sheet</button><button id="main-data-sheet-add" class="secondary" type="button">Add 10 rows</button><button id="main-data-sheet-download" class="secondary" type="button">Download Excel sheet</button></div></div><p id="main-data-sheet-message" class="hint" aria-live="polite"></p><div id="main-data-sheet-grid"></div></section>`);resetDataSheetForm=function(message=""){const box=$("main-data-sheet-message");if(box)box.textContent=message};renderDataSheet=function(){renderSpreadsheetGrid($("main-data-sheet-grid"),null)};setupSpreadsheetPage("main-data-sheet",null);renderDataSheet()}
function ensureExperimentDataSheet(){if($("experiment-data-sheet-page"))return;document.querySelector("main").insertAdjacentHTML("beforeend",`<section id="experiment-data-sheet-page" class="page hidden"><button class="secondary back" type="button" id="experiment-data-sheet-back">← Experiment</button><div class="intro"><h2 id="experiment-data-sheet-title">Experiment Data Sheet</h2><p>These rows belong only to this experiment. Use the vial or fertility-assay index in each row.</p></div><section class="panel spreadsheet-panel"><div class="spreadsheet-toolbar"><div><h3>Experiment measurements</h3><p class="hint">Type into cells directly, then choose Save Sheet.</p></div><div><button id="experiment-data-sheet-save" type="button">Save Sheet</button><button id="experiment-data-sheet-add" class="secondary" type="button">Add 10 rows</button><button id="experiment-data-sheet-download" class="secondary" type="button">Download Excel sheet</button></div></div><p id="experiment-data-sheet-message" class="hint" aria-live="polite"></p><div id="experiment-data-sheet-grid"></div></section></section>`);$("experiment-data-sheet-back").onclick=()=>window.controlRecord?openExperimentControl(window.controlRecord):page("experiments-page")}
function openExperimentDataSheet(record){ensureExperimentDataSheet();activeExperimentDataSheet=record;$("experiment-data-sheet-title").textContent=`(${barcodeFor(record)}) ${record.genotype} — Data Sheet`;$("experiment-data-sheet-message").textContent="";setupSpreadsheetPage("experiment-data-sheet",record);page("experiment-data-sheet-page")}
